// Offline mode: serve the app from precomputed JSON in public/data/ (generated by
// backend/scripts/export_static.py) when the Render backend is asleep or unreachable.
// Read-only endpoints map 1:1 to files; /predict and /best-time are reconstructed
// from the prediction table (every road x hour x day x weather x holiday).

const DATA_BASE = `${import.meta.env.BASE_URL}data/`;
const DAY_NAMES = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
const LEVELS = ['Low', 'Medium', 'High'];

const cache = new Map();
export function loadStatic(name) {
  if (!cache.has(name)) {
    const p = fetch(`${DATA_BASE}${name}`).then((r) => {
      if (!r.ok) throw new Error(`Offline data file ${name} is missing (${r.status}).`);
      return r.json();
    });
    p.catch(() => cache.delete(name));
    cache.set(name, p);
  }
  return cache.get(name);
}

export const slug = (text) => text.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const roadSuffix = (road) => (road && road !== 'all' ? `-${slug(road)}` : '');

// ----------------------------------------------------- US federal holidays
// Port of backend/app/holidays.py so future dates resolve the same way offline.
function nthWeekday(year, month, weekday, n) {
  // weekday: Mon=0 ... Sun=6 (Python convention); month: 1-12
  const jsDow = (d) => (d.getDay() + 6) % 7;
  if (n > 0) {
    const first = new Date(year, month - 1, 1);
    const offset = (weekday - jsDow(first) + 7) % 7;
    return new Date(year, month - 1, 1 + offset + 7 * (n - 1));
  }
  const last = new Date(year, month, 0);
  return new Date(year, month - 1, last.getDate() - ((jsDow(last) - weekday + 7) % 7));
}
const iso = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

function federalHolidays(year) {
  const out = {};
  for (const [m, d, name] of [[1, 1, "New Year's Day"], [6, 19, 'Juneteenth'], [7, 4, 'Independence Day'], [11, 11, 'Veterans Day'], [12, 25, 'Christmas Day']]) {
    const actual = new Date(year, m - 1, d);
    out[iso(actual)] = name;
    const dow = actual.getDay();
    if (dow === 6 || dow === 0) {
      const observed = new Date(year, m - 1, d + (dow === 6 ? -1 : 1));
      if (!out[iso(observed)]) out[iso(observed)] = `${name} (observed)`;
    }
  }
  out[iso(nthWeekday(year, 1, 0, 3))] = 'Martin Luther King Jr. Day';
  out[iso(nthWeekday(year, 2, 0, 3))] = "Presidents' Day";
  out[iso(nthWeekday(year, 5, 0, -1))] = 'Memorial Day';
  out[iso(nthWeekday(year, 9, 0, 1))] = 'Labor Day';
  out[iso(nthWeekday(year, 10, 0, 2))] = 'Columbus Day';
  out[iso(nthWeekday(year, 11, 3, 4))] = 'Thanksgiving Day';
  return out;
}
const holidayName = (dateIso) => federalHolidays(Number(dateIso.slice(0, 4)))[dateIso] || null;

// -------------------------------------------------------------- helpers
const parse = (dateIso) => {
  const [y, m, d] = dateIso.split('-').map(Number);
  return new Date(y, m - 1, d);
};
const dayIndex = (dateIso) => (parse(dateIso).getDay() + 6) % 7;
const hourLabel = (h) => `${String(h).padStart(2, '0')}:00`;
const hourRangeLabel = (h) => `${hourLabel(h)}-${hourLabel((h + 1) % 24)}`;
const pct = (a, b) => (b ? Math.round((a / b - 1) * 1000) / 10 : 0);

function resolveRoad(table, road) {
  const hit = table.roads.find((r) => r.toLowerCase() === String(road).toLowerCase());
  if (!hit) {
    const err = new Error(`Unknown road '${road}'. Available roads: ${table.roads.join(', ')}`);
    err.status = 404;
    throw err;
  }
  return hit;
}

/** Predicted cells for one road/date across hours, blending weathers for "auto". */
function predictHours(table, road, dateIso, weather, isHoliday) {
  const day = String(dayIndex(dateIso));
  const hol = isHoliday ? '1' : '0';
  const byWeather = table.values[road][day][hol];
  const month = String(parse(dateIso).getMonth() + 1);
  const mix = weather === 'auto' ? table.weather_mix_by_month[month] : { [weather]: 1 };
  return Array.from({ length: 24 }, (_, hour) => {
    let count = 0;
    let speed = 0;
    const probs = [0, 0, 0];
    for (const [w, share] of Object.entries(mix)) {
      const cell = byWeather[w][hour];
      count += cell[0] * share;
      speed += cell[1] * share;
      probs[0] += cell[3] * share;
      probs[1] += cell[4] * share;
      probs[2] += cell[5] * share;
    }
    const level = LEVELS[probs.indexOf(Math.max(...probs))];
    return { hour, count, speed, probs, level };
  });
}

// --------------------------------------------------------------- endpoints
export const offlineApi = {
  meta: () => loadStatic('meta.json'),
  summary: () => loadStatic('summary.json'),
  trends: (granularity = 'daily', road) => loadStatic(`trends-${granularity}${roadSuffix(road)}.json`),
  heatmap: (road, metric = 'vehicle_count') => loadStatic(`heatmap-${metric}${roadSuffix(road)}.json`),
  insights: (road) => loadStatic(`insights${roadSuffix(road)}.json`),
  modelMetrics: () => loadStatic('model-metrics.json'),

  async predict({ road, date, time, weather = 'sunny' }) {
    const table = await loadStatic('predictions.json');
    const r = resolveRoad(table, road);
    const hour = Number(String(time).slice(0, 2));
    const name = holidayName(date);
    const isHoliday = Boolean(name);
    const cell = predictHours(table, r, date, weather, isHoliday)[hour];
    const dow = dayIndex(date);
    const dayType = isHoliday ? 'holiday' : dow >= 5 ? 'weekend' : 'weekday';
    const typical = table.typical[r]?.[dayType]?.[hour] ?? null;
    const freeFlow = table.free_flow[r];
    const [lo, hi] = table.residual_ratio;
    return {
      road: r,
      date,
      time: hourLabel(hour),
      hour,
      day_of_week: DAY_NAMES[dow],
      weather,
      is_holiday: isHoliday,
      holiday_name: name,
      holiday_source: 'calendar',
      vehicle_count: Math.round(cell.count),
      vehicle_count_range: [Math.round(cell.count * lo), Math.round(cell.count * hi)],
      congestion_level: cell.level,
      congestion_probabilities: { Low: cell.probs[0], Medium: cell.probs[1], High: cell.probs[2] },
      average_speed: Math.round(cell.speed * 10) / 10,
      free_flow_speed: freeFlow,
      delay_pct: freeFlow ? Math.round(Math.max(0, 1 - cell.speed / freeFlow) * 1000) / 10 : 0,
      typical_vehicle_count: typical,
      vs_typical_pct: typical ? pct(cell.count, typical) : null,
      actual: null,
      model_used: table.model_used,
      warnings: [],
      offline: true,
    };
  },

  async bestTime({ road, date, weather = 'auto', start_hour = 0, end_hour = 23, top = 5 }) {
    const table = await loadStatic('predictions.json');
    const r = resolveRoad(table, road);
    const name = holidayName(date);
    const cells = predictHours(table, r, date, weather, Boolean(name));
    const start = Number(start_hour);
    const end = Number(end_hour);
    const hourly = cells.map((c) => ({
      hour: c.hour,
      label: hourLabel(c.hour),
      range_label: hourRangeLabel(c.hour),
      vehicle_count: Math.round(c.count),
      average_speed: Math.round(c.speed * 10) / 10,
      congestion_level: c.level,
      in_window: c.hour >= start && c.hour <= end,
    }));
    const windowHours = hourly.filter((h) => h.in_window);
    const ranked = [...windowHours].sort((a, b) => a.vehicle_count - b.vehicle_count || b.average_speed - a.average_speed);
    const worst = [...windowHours].sort((a, b) => b.vehicle_count - a.vehicle_count).slice(0, 3);
    const peak = worst[0]?.vehicle_count || 1;
    const best = ranked.slice(0, Math.max(1, Math.min(Number(top), ranked.length))).map((h) => ({
      ...h,
      savings_vs_peak_pct: Math.round((1 - h.vehicle_count / peak) * 1000) / 10,
    }));
    let block = null;
    if (windowHours.length >= 2) {
      let bestPair = null;
      for (let i = 0; i < windowHours.length - 1; i += 1) {
        const sum = windowHours[i].vehicle_count + windowHours[i + 1].vehicle_count;
        if (!bestPair || sum < bestPair.sum) bestPair = { a: windowHours[i], b: windowHours[i + 1], sum };
      }
      block = {
        start: bestPair.a.label,
        end: hourLabel((bestPair.b.hour + 1) % 24),
        start_hour: bestPair.a.hour,
        end_hour: (bestPair.b.hour + 1) % 24,
        avg_vehicle_count: Math.round(bestPair.sum / 2),
      };
    }
    const month = String(parse(date).getMonth() + 1);
    return {
      road: r,
      date,
      day_of_week: DAY_NAMES[dayIndex(date)],
      weather,
      weather_mix: weather === 'auto' ? table.weather_mix_by_month[month] : null,
      is_holiday: Boolean(name),
      holiday_name: name,
      window: { start_hour: start, end_hour: end },
      best_hours: best,
      worst_hours: worst,
      best_block: block,
      hourly,
      free_flow_speed: table.free_flow[r],
      model_used: table.model_used,
      offline: true,
    };
  },
};
